% =========================================================================
% Phase 2 (v2)：動態微動 + 拍頻訊號解析模型
% =========================================================================
fc = 60e9; bw = 4e9; sweepTime = 1e-3; c = 3e8; lambda = c/fc;
slope = bw/sweepTime;

fsFast = 2e6;                        % 快時間取樣率：只需涵蓋拍頻，不需涵蓋 4 GHz 帶寬
Ns = round(fsFast*sweepTime);        % 每個 chirp 2000 點
tf = (0:Ns-1)/fsFast;

fps = 100; duration = 10; numChirps = fps*duration;
timeVec = (0:numChirps-1)/fps;

Ar = 0.005; fr = 0.3;                % 呼吸：5 mm, 0.3 Hz
Ah = 0.0005; fh = 1.2;               % 心跳：0.5 mm, 1.2 Hz
R0 = 0.8;                            % 基礎距離 0.8 m

% 3. 慢時間迴圈：每個 chirp 的拍頻訊號 (Data Cube)
beatMatrix = zeros(Ns, numChirps);
for i = 1:numChirps
    disp_i = Ar*sin(2*pi*fr*timeVec(i)) + Ah*sin(2*pi*fh*timeVec(i));
    R   = R0 + disp_i;
    tau = 2*R/c;
    fb  = slope*tau;                                         % 拍頻
    beatMatrix(:,i) = exp(1j*(2*pi*fb*tf + 2*pi*fc*tau - pi*slope*tau^2));
end

% 4. Range FFT 與相位萃取
rangeFFT = fft(beatMatrix, [], 1);
f_axis     = fsFast*(0:floor(Ns/2))/Ns;
range_grid = f_axis*c/(2*slope);

mean_profile = mean(abs(rangeFFT(1:floor(Ns/2)+1,:)), 2);
[~, target_idx] = max(mean_profile);
fprintf('target_idx = %d, range bin = %.4f m（距離格解析度 %.2f cm）\n', ... %[output:group:2f15abde] %[output:2c70d554]
    target_idx, range_grid(target_idx), 100*c/(2*bw)); %[output:group:2f15abde] %[output:2c70d554]

extracted_phase = unwrap(angle(rangeFFT(target_idx,:)));
extracted_phase = extracted_phase - mean(extracted_phase);

% 5. 繪圖
figure; %[output:99f161ca]
plot(timeVec, extracted_phase, 'LineWidth', 1.5); %[output:99f161ca]
xlabel('Time (s)'); ylabel('Phase Variation (radians)'); %[output:99f161ca]
title('Digital Twin: Extracted Vital Sign Phase from FMCW Radar'); %[output:99f161ca]
grid on; %[output:99f161ca]

